  -- 📅 THÁNG 8/2026 (Đến 23/08: ODO: 2.265 km -> 2.651 km)
  ('20260801-0001-0000-0000-000000000058', v_mazda_id, v_device_id, '2026-08-01 08:30:00+07', '2026-08-01 09:20:00+07', 2265.0, 2292.0, 27.0, 3000, 32.4, 52.0, 21.3050, 105.3850, 21.3400, 105.4250, 'Nhà|Đi lại đầu tháng 8', 'COMPLETED'),
  ('20260804-0001-0000-0000-000000000059', v_mazda_id, v_device_id, '2026-08-04 07:45:00+07', '2026-08-04 09:15:00+07', 2292.0, 2351.0, 59.0, 5400, 39.3, 60.0, 21.3050, 105.3850, 21.3700, 105.4900, 'Nhà|Chuyến đi công việc', 'COMPLETED'),
  ('20260809-0001-0000-0000-000000000060', v_mazda_id, v_device_id, '2026-08-09 07:30:00+07', '2026-08-09 09:30:00+07', 2351.0, 2436.0, 85.0, 7200, 42.5, 65.0, 21.3050, 105.3850, 21.2500, 105.5400, 'Nhà|Hành trình cuối tuần', 'COMPLETED'),
  ('20260814-0001-0000-0000-000000000061', v_mazda_id, v_device_id, '2026-08-14 08:00:00+07', '2026-08-14 08:55:00+07', 2436.0, 2470.0, 34.0, 3300, 37.1, 55.0, 21.3050, 105.3850, 21.3450, 105.4350, 'Nhà|Đi lại công việc', 'COMPLETED'),
  ('20260815-0001-0000-0000-000000000062', v_mazda_id, v_device_id, '2026-08-15 09:00:00+07', '2026-08-15 09:50:00+07', 2470.0, 2506.0, 36.0, 3000, 43.2, 58.0, 21.3050, 105.3850, 21.3450, 105.4400, 'Nhà|Di chuyển cuối tuần', 'COMPLETED'),
  ('20260820-0001-0000-0000-000000000063', v_mazda_id, v_device_id, '2026-08-20 07:30:00+07', '2026-08-20 09:45:00+07', 2506.0, 2602.0, 96.0, 8100, 42.7, 68.0, 21.3050, 105.3850, 21.1800, 105.6200, 'Nhà|Chuyến đi công tác tỉnh xa', 'COMPLETED'),
  ('20260823-0001-0000-0000-000000000064', v_mazda_id, v_device_id, '2026-08-23 08:00:00+07', '2026-08-23 09:15:00+07', 2602.0, 2651.0, 49.0, 4500, 39.2, 60.0, 21.3050, 105.3850, 21.3600, 105.4700, 'Nhà|Hành trình cuối tuần trước khi bật CarLogger', 'COMPLETED')
  ON CONFLICT (id) DO UPDATE SET
    start_odometer = EXCLUDED.start_odometer,
    end_odometer = EXCLUDED.end_odometer,
    distance_km = EXCLUDED.distance_km,
    notes = EXCLUDED.notes;

  -- 5. XÓA CÁC CHUYẾN TRÔI GPS ĐỨNG YÊN (< 200m) GIAI ĐOẠN OBD (TỪ 24/08 ĐẾN NAY)
  DELETE FROM public.trips
  WHERE asset_id = v_mazda_id
    AND start_time >= '2026-08-24'
    AND (distance_km < 0.2 OR distance_km IS NULL);

  -- 6. TÍNH TỔNG QUÃNG ĐƯỜNG ĐANG CÓ CỦA CÁC CHUYẾN OBD (TỪ 24/08)
  SELECT COALESCE(SUM(distance_km), 0)
  INTO v_obd_sum
  FROM public.trips
  WHERE asset_id = v_mazda_id
    AND start_time >= '2026-08-24';

  -- 7. CÂN CHỈNH TỶ LỆ CÁC CHUYẾN OBD ĐỂ TỔNG ĐẠT ĐÚNG 329,00 KM (2.651 km -> 2.980 km)
  IF v_obd_sum > 0 THEN
    v_scale := v_target_obd_dist / v_obd_sum;
  END IF;

  FOR v_trip IN
    SELECT id, distance_km
    FROM public.trips
    WHERE asset_id = v_mazda_id
      AND start_time >= '2026-08-24'
    ORDER BY start_time ASC
  LOOP
    UPDATE public.trips
    SET 
      distance_km = ROUND((v_trip.distance_km * v_scale)::numeric, 2),
      start_odometer = ROUND(v_running_odo::numeric, 2),
      end_odometer = ROUND((v_running_odo + (v_trip.distance_km * v_scale))::numeric, 2)
    WHERE id = v_trip.id;

    v_running_odo := v_running_odo + (v_trip.distance_km * v_scale);
  END LOOP;

  -- 8. CHỐT CHẶNG CUỐI CÙNG ĐÚNG CHÍNH XÁC MỐC 2.980,00 KM
  UPDATE public.trips
  SET end_odometer = 2980.0
  WHERE id = (
    SELECT id FROM public.trips 
    WHERE asset_id = v_mazda_id 
    ORDER BY start_time DESC LIMIT 1
  );

  -- 9. CẬP NHẬT CHUẨN ODOMETER TRONG BẢNG ASSETS LÊN 2.980 KM
  UPDATE public.assets
  SET 
    current_odometer_km = 2980,
    virtual_odometer_km = 2980,
    initial_odometer_km = 12,
    updated_at = NOW()
  WHERE id = v_mazda_id;

  RAISE NOTICE 'Đã cân chỉnh hoàn tất toàn bộ chuyến đi! Tổng km các chuyến = ODO xe = 2.980 KM!';
END $$;

